import {shuffle} from './core.js?v=15';
import {ContinuousPdfViewer} from './continuous-pdf.js?v=1';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seasons={m:'2–3月',s:'5–6月',w:'10–11月'},groups={'mcq-theory':'选择与理论',practical:'实验题'};
let bank,taxonomy,group='mcq-theory',year='',session='',record='all',query='',allowCross=true,selectedSections=[],limit=8,order=new Map();
let state={saved:[],done:[]},notes={};const opened=new Set();
try{const value=JSON.parse(localStorage.getItem('pure-physics-records-v1')||'{}');if(Array.isArray(value.saved)&&Array.isArray(value.done))state=value}catch{}
try{const value=JSON.parse(localStorage.getItem('pure-physics-notes-v1')||'{}');if(value&&typeof value==='object'&&!Array.isArray(value))notes=value}catch{}
function saveState(){localStorage.setItem('pure-physics-records-v1',JSON.stringify(state));}
function saveNotes(){localStorage.setItem('pure-physics-notes-v1',JSON.stringify(notes));}
function allSectionIds(){return taxonomy.chapters.flatMap(chapter=>chapter.sections.map(section=>section.id));}
function selectedMatch(question){if(!selectedSections.length)return false;return allowCross?question.sections.some(id=>selectedSections.includes(id)):question.sections.every(id=>selectedSections.includes(id));}
function pool(){const term=query.trim().toLowerCase();return bank.questions.filter(question=>question.group===group&&(!year||question.year===+year)&&(!session||question.session===session)&&selectedMatch(question)&&(record==='all'||record==='saved'&&state.saved.includes(question.id)||record==='done'&&state.done.includes(question.id)||record==='undone'&&!state.done.includes(question.id))&&(!term||[question.id,question.year,question.number,question.searchText,...question.sections,...taxonomy.chapters.flatMap(c=>c.sections.filter(s=>question.sections.includes(s.id)).flatMap(s=>[s.title,s.zh]))].join(' ').toLowerCase().includes(term))).sort((a,b)=>order.get(a.id)-order.get(b.id));}
function sectionName(id){for(const chapter of taxonomy.chapters){const section=chapter.sections.find(item=>item.id===id);if(section)return `${id} ${section.zh}`;}return id;}
function chapterControls(){const counts=new Map(allSectionIds().map(id=>[id,bank.questions.filter(q=>q.group===group&&q.sections.includes(id)).length]));$('#physics-chapters').innerHTML=taxonomy.chapters.map(chapter=>`<details class="physics-section" open><summary>${chapter.id} · ${esc(chapter.zh)}</summary><div class="physics-section-list">${chapter.sections.map(section=>`<label><input type="checkbox" value="${section.id}" ${selectedSections.includes(section.id)?'checked':''}><span>${section.id} · ${esc(section.zh)}<small>${esc(section.title)} · ${counts.get(section.id)}题</small></span></label>`).join('')}</div></details>`).join('');}
let pdfjs=null;const documents=new Map();
async function renderCrop(canvas){const data=JSON.parse(decodeURIComponent(canvas.dataset.pdfCrop));pdfjs??=await import('./assets/pdfjs/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./assets/pdfjs/pdf.worker.mjs',import.meta.url).href;let promise=documents.get(data.pdf);if(!promise){promise=pdfjs.getDocument({url:data.pdf,isEvalSupported:false}).promise;documents.set(data.pdf,promise);}const pdf=await promise,page=await pdf.getPage(data.page),viewport=page.getViewport({scale:1.45}),[x,y,w,h]=data.crop;canvas.width=Math.max(1,Math.round(viewport.width*w));canvas.height=Math.max(1,Math.round(viewport.height*h));const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);await page.render({canvasContext:context,viewport,transform:[1,0,0,1,-viewport.width*x,-viewport.height*y]}).promise;canvas.dataset.ready='true';}
const cropObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){const canvas=entry.target;cropObserver.unobserve(canvas);canvas.dataset.ready='loading';renderCrop(canvas).catch(error=>{canvas.dataset.ready='error';console.error(error);});}},{rootMargin:'500px'});
function cropImages(pages,title){return pages.map(page=>{const label=`${title}，原文件第${page.page}页`;return `<figure><button class="past-image-link" data-doc="${page.pdf}" data-page="${page.page}" data-title="${esc(title)}" aria-label="${esc(label)}"><canvas class="source-pdf-crop" data-pdf-crop="${encodeURIComponent(JSON.stringify(page))}" aria-label="${esc(label)}"></canvas></button></figure>`;}).join('');}
function note(question){return `<section class="physics-note" data-note-id="${question.id}"><details ${notes[question.id]?'open':''}><summary>我的备注${notes[question.id]?' · 编辑':' · 添加'}</summary><textarea maxlength="10000" rows="4" placeholder="记录错因、思路或需要复习的内容">${esc(notes[question.id]||'')}</textarea><small>${(notes[question.id]||'').length}/10000 · 自动保存在本机</small></details></section>`;}
function card(question){const paper=bank.papers.find(item=>item.id===question.paper),saved=state.saved.includes(question.id),done=state.done.includes(question.id),type=question.paperType<=2?'选择题':question.paperType<=4?'理论题':'实验题';return `<article class="question-card past-card" data-id="${question.id}"><div class="card-head"><div class="card-meta"><span class="q-number">Question ${question.number}</span><span class="tag">${type} · 真题</span></div><div class="card-actions"><button class="small-action ${saved?'on':''}" data-save="${question.id}" aria-pressed="${saved}">${saved?'已收藏':'收藏'}</button><button class="small-action ${done?'on':''}" data-done="${question.id}" aria-pressed="${done}">${done?'已做':'未做'}</button></div></div><div class="past-images">${cropImages(question.pages,`Physics 0625 · Question ${question.number}`)}</div><div class="card-footer"><button class="answer-toggle" data-answer="${question.id}" aria-expanded="${opened.has(question.id)}">${opened.has(question.id)?'收起答案':'查看官方答案'}</button><button class="text-button" data-doc="${paper.qp}" data-page="${question.pages[0].page}" data-title="${esc(paper.title)} · Question ${question.number}">查看原题</button><button class="text-button" data-doc="${paper.ms}" data-page="${question.markSchemePages[0].page}" data-title="${esc(paper.title)} · 官方评分标准">完整评分标准</button>${question.marks?`<span class="total-marks">Total <strong>${question.marks}</strong> marks</span>`:''}</div><section class="past-solution" id="solution-${question.id}" ${opened.has(question.id)?'':'hidden'}><h3>官方答案与评分标准</h3><p class="question-coverage"><b>考查范围：</b>${question.sections.map(sectionName).join('、')}</p><p class="physics-question-source">来源：${esc(paper.title)} · 0625/${paper.paper} · Question ${question.number}</p>${question.answer?`<p class="physics-answer-key">答案：${esc(question.answer==='Question Discounted'?'本题取消计分（Question Discounted）':question.answer)}</p>`:''}<div class="official-scheme-images">${cropImages(question.markSchemePages,`${paper.title} · Question ${question.number} · 官方评分标准`)}</div><p class="physics-question-source">${esc(question.verification)}</p></section>${note(question)}</article>`;}
function mountCrops(){for(const canvas of document.querySelectorAll('canvas[data-pdf-crop]:not([data-ready])'))cropObserver.observe(canvas);}
function render(){const list=pool(),visible=list.slice(0,limit);$('#physics-count').textContent=`2019—2024 · ${list.length} 道题`;$('#physics-heading').textContent=`${groups[group]} · 逐题练习`;$('#physics-all-nav').classList.toggle('active',record!=='saved');$('#physics-saved-nav').classList.toggle('active',record==='saved');$('#physics-results').innerHTML=`<div class="result-row"><span>当前筛选 <strong>${list.length}</strong> 道题</span><span>已显示 ${visible.length} 道</span></div>${visible.length?visible.map(card).join(''):'<div class="empty"><h2>没有符合条件的真题</h2><p>请调整章节、年份或记录筛选。</p></div>'}${visible.length<list.length?'<div id="physics-more" class="physics-load-sentinel">继续向下滑动加载…</div>':''}`;mountCrops();const more=$('#physics-more');if(more)moreObserver.observe(more);}
const moreObserver=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){limit+=8;render();}},{rootMargin:'500px'});
function reset(){year=session=query='';record='all';allowCross=true;selectedSections=allSectionIds();limit=8;$('#physics-year').value='';$('#physics-session').value='';$('#physics-record').value='all';$('#physics-search').value='';$('#physics-cross-chapter').checked=true;chapterControls();render();}
let doc=null,scale=1,token=0;const viewer=new ContinuousPdfViewer({container:$('#reader-scroll'),pagesRoot:$('#reader-pages'),pageLabel:$('#reader-page'),error:error=>{console.error(error);$('#reader-message').textContent='部分页面暂时无法显示，可打开原文件阅读。';}});
async function openDoc(url,title,page=1){const current=++token;if(!$('#physics-reader').open)$('#physics-reader').showModal();$('#reader-title').textContent=title;$('#reader-source').href=url+'#page='+page;$('#reader-message').textContent='正在读取原文件…';scale=1;try{pdfjs??=await import('./assets/pdfjs/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./assets/pdfjs/pdf.worker.mjs',import.meta.url).href;const next=await pdfjs.getDocument({url,isEvalSupported:false}).promise;if(current!==token){next.destroy();return;}doc?.destroy();doc=next;$('#reader-message').textContent='';await viewer.open(doc,{page,zoom:scale});}catch(error){$('#reader-message').textContent='内嵌阅读暂未载入，可点击“原文件”打开。';console.error(error);}}
async function init(){try{const [bankResponse,taxonomyResponse]=await Promise.all([fetch('data/physics-question-bank.json?v=1'),fetch('data/physics-chapters.json?v=1')]);if(!bankResponse.ok||!taxonomyResponse.ok)throw Error('题库文件不可用');bank=await bankResponse.json();taxonomy=await taxonomyResponse.json();selectedSections=allSectionIds();order=new Map(shuffle(bank.questions.map(q=>q.id)).map((id,index)=>[id,index]));$('#physics-year').innerHTML='<option value="">全部年份</option>'+[...new Set(bank.papers.map(p=>p.year))].sort((a,b)=>b-a).map(value=>`<option>${value}</option>`).join('');if(innerWidth<=700)$('#physics-filters').open=false;chapterControls();render();
$('#physics-saved-nav').onclick=()=>{record='saved';$('#physics-record').value='saved';limit=8;render();scrollTo({top:0,behavior:'smooth'});};$('#physics-group').onchange=e=>{group=e.target.value;selectedSections=allSectionIds();limit=8;chapterControls();render();};$('#physics-year').onchange=e=>{year=e.target.value;limit=8;render();};$('#physics-session').onchange=e=>{session=e.target.value;limit=8;render();};$('#physics-record').onchange=e=>{record=e.target.value;limit=8;render();};$('#physics-search').oninput=e=>{query=e.target.value;limit=8;render();};$('#physics-cross-chapter').onchange=e=>{allowCross=e.target.checked;limit=8;render();};$('#physics-reset').onclick=reset;$('#physics-shuffle').onclick=()=>{order=new Map(shuffle(bank.questions.map(q=>q.id)).map((id,index)=>[id,index]));limit=8;render();$('#physics-results').scrollIntoView({behavior:'smooth'});};$('#physics-all').onclick=()=>{selectedSections=allSectionIds();chapterControls();limit=8;render();};$('#physics-clear').onclick=()=>{selectedSections=[];chapterControls();limit=8;render();};$('#physics-chapters').onchange=()=>{selectedSections=[...document.querySelectorAll('#physics-chapters input:checked')].map(input=>input.value);limit=8;render();};
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.answer){const id=button.dataset.answer;opened.has(id)?opened.delete(id):opened.add(id);render();requestAnimationFrame(()=>document.querySelector(`[data-id="${id}"]`)?.scrollIntoView({block:'nearest'}));}for(const [field,key] of [['save','saved'],['done','done']])if(button.dataset[field]){const id=button.dataset[field];state[key]=state[key].includes(id)?state[key].filter(item=>item!==id):[...state[key],id];saveState();render();}if(button.dataset.doc)openDoc(button.dataset.doc,button.dataset.title,+button.dataset.page||1);});document.addEventListener('input',event=>{if(!event.target.matches('.physics-note textarea'))return;const id=event.target.closest('[data-note-id]').dataset.noteId,value=event.target.value;value?notes[id]=value:delete notes[id];saveNotes();event.target.nextElementSibling.textContent=`${value.length}/10000 · 自动保存在本机`;});
$('#reader-close').onclick=()=>$('#physics-reader').close();$('#reader-prev').onclick=()=>viewer.go(viewer.current-1);$('#reader-next').onclick=()=>viewer.go(viewer.current+1);$('#reader-plus').onclick=()=>{scale=Math.min(2.5,scale+.2);viewer.setZoom(scale);$('#reader-zoom').textContent=Math.round(scale*100)+'%';};$('#reader-minus').onclick=()=>{scale=Math.max(.6,scale-.2);viewer.setZoom(scale);$('#reader-zoom').textContent=scale===1?'适合宽度':Math.round(scale*100)+'%';};$('#reader-full').onclick=async()=>{const on=$('#physics-reader').classList.toggle('expanded');$('#reader-full').textContent=on?'退出全屏':'全屏阅读';try{if(on&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else if(!on&&document.fullscreenElement)await document.exitFullscreen();}catch{}viewer.resize();};$('#physics-reader').addEventListener('close',()=>{token++;viewer.destroyDocument();doc?.destroy();doc=null;});}catch(error){console.error(error);$('#physics-results').textContent='物理真题题库未能载入，请刷新页面重试。';}}
init();
